import{_ as t,o,c as s,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Issues with Publishing Results","description":"","frontmatter":{"translationSource":{"title":"成果公开流程问题总结","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=bjB7jF3g7E11H2AlmcZ3JQ","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/issues-with-publishing-results"}]]},"headers":[],"relativePath":"issues-with-publishing-results.md","filePath":"logistics/src/page-bjB7jF3g7E11H2AlmcZ3JQ.md"}'),n={name:"issues-with-publishing-results.md"};function a(r,e,p,l,d,u){return o(),s("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="成果公开流程问题总结" aria-hidden="true"></span><h1 id="issues-with-publishing-results" tabindex="-1">Issues with Publishing Results <a class="header-anchor" href="#issues-with-publishing-results" aria-label="Permalink to &quot;Issues with Publishing Results&quot;">​</a></h1><blockquote><p>Source page ID: <code>bjB7jF3g7E11H2AlmcZ3JQ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=bjB7jF3g7E11H2AlmcZ3JQ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Collect problems and group members&#39; suggestions arising during publication, including technical writing, video production, video-feedback effects, support, etc.</p><p><strong>Q1 Are blueprint codes necessary?</strong></p><p>Brief: videos provide codes but partly discourage use. Is this contradictory or unnecessary?</p><p>四卡一: Ask who this is for. If showing off technique, codes are unnecessary; if a public build to copy, optimize compatibility. The current halfway discouragement satisfies neither side.</p><p>言: Necessary; emphasize positioning. Point out drawbacks, especially the “self-troubleshooting hell.”</p><p>鸟: Still necessary; at least interested learners can study them.</p><p>加兰斯: Start the next video with a disclaimer: some AIC foundation is required.</p><p>(09-16)</p><p><strong>Q2 Where should blueprint codes go?</strong></p><p>Brief: at the beginning or end of the task board&#39;s public documentation?</p><p>[Ѵ. Ŋøᵰę]ᵱ: For the public, move documentation and codes forward first, then FAQs; put detailed technical material in subpages. So FAQs first, codes next, everything else in subpages. Make another video emotionally reading How to Ask Questions the Smart Way.</p><p>言: Put them first and nobody reads the rest, then asks when things break. Putting them later forces a skim. After K persuaded me: “Then I will put them at the front.”</p><p>K: Skimming just means looking for a code, as useless as software user agreements. (Even maa notices requiring scrolling to the bottom do not make some people read.)</p><p>Cipolla_: Is that code seriously after the FAQ? I really want to edit it myself.</p><p>BEAR: Put codes in the document; placement on part 2.</p><p>言 (Talos-II, 09-08): Add “blueprint codes update more slowly than the document” to the description, prioritizing the document.</p><p>(09-16; Talos-II 09-08)</p><p><strong>Q3 Lack of Unified Decisions and Proofreading</strong></p><p>Brief: everyone works separately; handoffs fail, assignments are abnormal, and results lack proofreading.</p><p>区: Scale increased; coordination, decisions, and operations did not keep up.</p><p>K: 言 is impressive, but we lack a central figure/headquarters/someone to coordinate or take the blame.</p><p>BEAR: We have no deadlines. Boss, enforce deadlines next time.</p><p>S: We really need a proofreading team. Everyone works separately; nothing connects.</p><p>[Ѵ. Ŋøᵰę]ᵱ: I did not even know my document&#39;s code no longer matched the video. At least message people privately before editing their documents.</p><p>言: Oh no, I thought your Jingyu Valley setup was unchanged and copied the link directly.</p><p>(09-16)</p><p>Talos-II (08-03), 忉牿: Errors are normal; no errors would be rare. 急急急妞呢小: There are so many errors; it feels unproofread, perhaps printed without even reading. 君: Where do we find a proofreader? It costs money. 苍孤狼: Is one AI proofreading pass so hard? → 忉牿: Would AI guarantee success? → 苍孤狼: Would a human? Nothing is 100%, but surely much better than the current situation.</p><p><strong>Q4 Support and Customer-Service Burden</strong></p><p>Brief: answering questions after publication is burdensome, staffing insufficient, and responsibility unclear.</p><p>言: Could we cooperate on support? We lack the energy. Large creators are valuable partners because they handle support well and understand users better.</p><p>BEAR: Better worry who is responsible when support goes wrong.</p><p>鸟: The support provider (jk); train 君 as customer service (jk).</p><p>区: The hardest, most exhausting work, and complaints too?</p><p>君: How can we focus on players without wages?</p><p>麻: We barely even do part-time support.</p><p>阳桃: Should we consider a dedicated support group? (</p><p>Zirunwang: After enough customer-service work, you become numb.</p><p>Witherlin凋灵灵: Could we feed group resources to AI and build an AI support agent?</p><p>二律背反: My support stream these two days: “Why is my Chubby Lung not producing?” Turns out the recipe was not unlocked. However idiot-proof a blueprint is, comments make you wish it were more so.</p><p>Talos-II: ☢caution☢: “Service is lacking; people see a blueprint creator with no support.” Fatal Error A1012: “You can find the video, but must start it yourself and debug after offline operation, so no support is provided.”</p><p>(09-12 ~ 09-26; Talos-II 04-19, 05-06)</p><p><strong>Q5 Long Documents Discourage the Audience</strong></p><p>百亿亿亿亿: I gave them the document link too, but many were put off by the huge amount of text. We should avoid discouraging people unfamiliar with AIC.</p><p>良木: Forget it; most probably will not read documentation.</p><p>断懒: People do not even watch content already in the video. They ask about things I emphasized 3 times. Make separate parts explaining every possible problem; keep engineering documentation and update weekly.</p><p>二律背反: They do not watch videos either. However simple, they cannot do it.</p><p>区: Idiot-proofing has no endpoint. University courses should not cater to elementary-school pupils.</p><p>Cipolla_: Most people not reading FAQs is fine. For viewers with some foundation or interest, our technical explanation videos should come out.</p><p>Q6 Blueprint Codes / Videos / Documentation Out of Sync</p><p>Brief: revisions, text edits, and account changes cause mismatches; viewers receive wrong codes.</p><p>四卡一: “Why is the code invalid?” is so common I cannot be bothered complaining. Was the earliest code wrong?</p><p>言: Many errors with this set were unconnected acid, water, or Inergen.</p><p>[Ѵ. Ŋøᵰę]ᵱ: Your modified version does not match my video.</p><p>夏后曦和: Endfield&#39;s blueprint system is frustrating: changing one character and resaving changes the share code. When problems arise, I immediately suspect a blueprint bug.</p><p>盒え猫: Different people wrote it.</p><p>K: The task board is quite messy. There is a hyperlink to your all-item document; should it be deleted?</p><p>断懒: Do not enter codes manually or from screenshots. No spaces before or after them.</p><p>PL: Blueprints have text limits. Can instructions fit near the code in the video description? The placement video can say it too.</p><p>BEAR: Should we make one definitive code for 1.5 gross output?</p><p>jnk (Talos-II): The code&#39;s uid is the main account; the video shows an alternate account.</p><p>言 (09-26): Should we put the codes into the archive?</p><p><strong>Q7 Who Is This For: Showing Off, Guides, or Education?</strong></p><p>Brief: the team never settled its audience, leaving content and assistance without a clear direction.</p><p>区: Our videos are just self-indulgent technical showing-off online. 流星飞&#39;s blueprints target the public, so likely face more such questions. University courses should not cater to elementary-school pupils (provocative claim).</p><p>君: Define the user group properly. (言: Yes.)</p><p>言: This promotion was too strong; our positioning was unclear. Time to discuss “explaining clearly and concisely to the public.” Lower the barrier to figuring it out yourself; simply explain the modules once.</p><p>断懒: Reaffirm the video&#39;s research positioning, rather than a guide. (言: Agreed.) Last version I planned basic AIC teaching this version, but forgot. Are pure equipment manuals and line explanations too superficial?</p><p>BEAR: Mainly showing off (as 君 said). Our design is a technical showcase; no rush.</p><p>百亿亿亿亿: Many are discouraged by huge text. Education means giving examples in extremely plain language, at least attracting people.</p><p>言 (09-13): Both adaptation and automatic balancing should be explained. Boss bird explained them, yet views/comments were dismal. Does nobody read pinned comments? Must it be even simpler, omitting more assumptions? Popular education is too profound.</p><p>S: Using this has a barrier; adaptive setups have a much higher barrier than ordinary copied blueprints, because adaptation ultimately targets newcomers.</p><p>K: Treat users as blind. (); 君: But surely not this blind.</p><p>c: AIC&#39;s barrier is too high. Why does it feel like a 0 barrier to me? Copying has no barrier; fixing bugs does.</p><p>乾震_QzzZ: Without beauty or fun as motivation, difficulty alone makes the barrier too high and the audience ever smaller. Lower barriers and increase enjoyment. AIC&#39;s barrier is so high that once crossed, you have already graduated.</p><p>S and c (09-17): Are compatibility and entry barrier the same thing?</p><p>断懒, 浅仓透: Separate teaching is better; interested learners search for tutorials themselves.</p><p>PL: AIC controversy comes from too few main-story tutorials and an unreasonable difficulty curve; add more AIC content. 言: Games and players should choose each other; if unsuitable, do not play. → PL: That is punishment without teaching. → 盒え猫: More AIC will inevitably provoke some opposition. 言: Gameplay needs depth and broad participation to stay alive.</p><p>Talos-II, xyIvneu_: We make educational videos; audiences differ. This suits deeply invested people; zmd suits science/engineering people. c: zmd is AIC gameplay; the audience is small anyway. Cipolla_: Textbook form does narrow the audience, but someone will read it. Xersyo: Essentially a research group.</p><p>(Bureau 09-11 ~ 09-21; Talos-II 04-05, 04-25, 08-06, 09-11)</p></div>',1)])])}const m=t(n,[["render",a]]);export{h as __pageData,m as default};
